"""Beginner guidance in existing theory/requirement/explanation string fields.

Examples are illustrative, not session fixtures. Reference SQL stays private.
"""
LABELS = {
    "ENG": ("What are we checking?", "Why does this matter?", "Small worked example — illustrative", "Common mistake", "Challenge explained", "Solution explained"),
    "VIE": ("Chúng ta đang kiểm tra gì?", "Vì sao điều này quan trọng?", "Ví dụ nhỏ — chỉ để minh họa", "Lỗi thường gặp", "Giải thích thử thách", "Giải thích lời giải"),
}


def sections(language, parts):
    labels = LABELS[language]
    return "\n\n".join(labels[index] + "\n" + body for index, body in parts)


