def apply_guidance(catalog):
    for lab_id, translations in GUIDANCE.items():
        for language, (checking, purpose, example, mistake, challenge, solution) in translations.items():
            text = catalog[lab_id][language]
            text["theory"] = sections(language, ((0, checking), (1, purpose), (2, example), (3, mistake)))
            text["requirement"] += "\n\n" + sections(language, ((4, challenge),))
            text["explanation"] = sections(language, ((5, solution),))
